using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Anis.Partners.Sdk.Enrollment;
using Anis.Partners.Sdk.Errors;
using Anis.Partners.Sdk.Models;
using Anis.Partners.Sdk.Observability;
using Anis.Partners.Sdk.Verification;

namespace Anis.Partners.Sdk.Tests;

/// <summary>Enrollment: the possession proof Anis verifies, and the walk from invitation to proof.</summary>
/// <remarks>
/// The proof vectors were generated by the conformance tool and cross-validated against COMMANDS' own
/// <c>ProofVerification</c> — the code that decides whether a proof is accepted — so a failure here means
/// the SDK no longer proves possession in the form Anis verifies.
/// </remarks>
public sealed class EnrollmentTests
{
    private const string ResponseKeyId = "partner-response-signing/v1-active";
    private const string Token = "enrollment-token-7Qm2Xv9Lp4Rk8Tz1Wc6Nb3Hs5Jd0Fg";

    private static readonly Guid Invitation = Guid.Parse("3f2a9c14-8d6e-4b21-9f07-5c8ab2d61e43");
    private static readonly DateTimeOffset Now = DateTimeOffset.FromUnixTimeSeconds(1789804800);

    public static TheoryData<string> Vectors
    {
        get
        {
            var directory = Path.Combine(AppContext.BaseDirectory, "vectors", "enrollment");

            var files = Directory.Exists(directory)
                ? Directory.GetFiles(directory, "EP-*.json").Order(StringComparer.Ordinal).ToArray()
                : [];

            Assert.True(files.Length > 0, $"No enrollment proof vectors were found under {directory}.");

            return new TheoryData<string>(files);
        }
    }

    [Theory]
    [MemberData(nameof(Vectors))]
    public async Task The_sdk_builds_the_proof_Commands_verifies(string path)
    {
        var vector = JsonDocument.Parse(await File.ReadAllTextAsync(path, TestContext.Current.CancellationToken)).RootElement;
        var result = vector.GetProperty("keySubmissionResult");
        var expected = vector.GetProperty("expected");

        var submitted = new EnrollmentKeyResult
        {
            KeyId = Guid.Parse(result.GetProperty("keyId").GetString()!),
            Thumbprint = result.GetProperty("thumbprint").GetString(),
            Challenge = result.GetProperty("challenge").GetString(),
            ChallengeGeneration = result.GetProperty("challengeGeneration").GetInt32(),
        };

        // The message is deterministic: byte for byte what Anis rebuilds.
        var message = AnisEnrollmentClient.ProofMessage(submitted);

        Assert.Equal(expected.GetProperty("proofMessageBase64").GetString(), Convert.ToBase64String(message));

        using var key = ECDsa.Create();
        key.ImportPkcs8PrivateKey(Convert.FromBase64String(vector.GetProperty("key").GetProperty("privateKeyPkcs8Base64").GetString()!), out _);

        var proof = AnisEnrollmentClient.CreateProof(submitted, key);

        // The signature differs every run; its form and its validity do not.
        Assert.Equal(submitted.KeyId, proof.KeyId);
        Assert.Equal(submitted.ChallengeGeneration, proof.ChallengeGeneration);
        Assert.Equal(86, proof.Signature.Length);
        Assert.DoesNotContain('=', proof.Signature);
        Assert.DoesNotContain('+', proof.Signature);
        Assert.DoesNotContain('/', proof.Signature);

        Assert.True(Verifies(key, message, proof.Signature), "The SDK's proof does not verify over Anis's message.");
        Assert.True(Verifies(key, message, vector.GetProperty("exampleSignature").GetString()!), "The vector's example proof does not verify.");
    }

    [Fact]
    public void A_der_signature_is_refused_before_it_reaches_Anis()
    {
        using var key = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        var submitted = Submitted();

        var der = key.SignData(AnisEnrollmentClient.ProofMessage(submitted), HashAlgorithmName.SHA256, DSASignatureFormat.Rfc3279DerSequence);

        Assert.Throws<ArgumentException>(() => AnisEnrollmentClient.CreateProof(submitted, der));
    }

    [Fact]
    public void A_key_on_another_curve_is_refused()
    {
        using var key = ECDsa.Create(ECCurve.NamedCurves.nistP384);

        Assert.Throws<ArgumentException>(() => AnisEnrollmentClient.CreateProof(Submitted(), key));
    }

    [Fact]
    public void A_submission_result_without_its_challenge_cannot_be_proved()
        => Assert.Throws<ArgumentException>(() => AnisEnrollmentClient.ProofMessage(Submitted() with { Challenge = null }));

    [Fact]
    public async Task Submit_then_prove_walks_the_enrollment_routes_and_verifies_every_answer()
    {
        using var responseKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        using var partnerKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        using var capture = new TelemetryCapture();

        var stub = new SignedResponseStub(responseKey, ResponseKeyId) { SignedAt = Now, NoStore = true };

        var thumbprint = KeyThumbprint.Compute(AnisEnrollmentClient.PublicJwkOf(partnerKey));

        stub.Bodies.Enqueue($$"""{"keyId":"{{Invitation:D}}","thumbprint":"{{thumbprint}}","challenge":"tX3vQ9m2Lr8Kc4Hw1Zp7Ns0Ye6Ud5Jb2Gf9Aq3Vk8Mo","challengeGeneration":1}""");
        stub.Bodies.Enqueue($$"""{"keyId":"{{Invitation:D}}","challengeGeneration":1,"proofState":"accepted","approvalState":"pending","state":"pendingApproval"}""");

        using var enrollment = AnisEnrollmentClient.Create(
            new Uri("https://partners.anis.ly"), Invitation, Token, KeysFor(responseKey), stub, new FixedClock(Now));

        var submitted = await enrollment.SubmitKeyAsync(
            new EnrollmentKeyRequest
            {
                PublicJwk = AnisEnrollmentClient.PublicJwkOf(partnerKey),
                NotBefore = Now,
                ExpiresAt = Now.AddYears(1),
            },
            TestContext.Current.CancellationToken);

        // The SDK derives the safety code from the thumbprint it has just checked.
        Assert.Equal(thumbprint, submitted.Thumbprint);
        Assert.Equal(SafetyCode.FromThumbprint(thumbprint), submitted.SafetyCode);

        var status = await enrollment.ProveAsync(submitted, partnerKey, TestContext.Current.CancellationToken);

        Assert.Equal("pendingApproval", status.State);
        Assert.Equal("accepted", status.ProofState);

        // Two requests, both on the enrollment branch: the token, and no message signature at all.
        Assert.Equal(2, stub.Requests.Count);
        Assert.All(stub.Requests, request =>
        {
            Assert.Equal($"Enrollment {Token}", request.Headers.GetValues("Authorization").Single());
            Assert.False(request.Headers.Contains("Signature"));
        });

        Assert.Equal($"/v1/enrollments/{Invitation:D}/keys", stub.Requests[0].RequestUri!.AbsolutePath);
        Assert.Equal($"/v1/enrollments/{Invitation:D}/proof", stub.Requests[1].RequestUri!.AbsolutePath);

        // The proof that went out is the one Anis verifies.
        var sent = JsonDocument.Parse(stub.LastRequestBody!).RootElement;

        Assert.Equal(Invitation.ToString("D"), sent.GetProperty("keyId").GetString());
        Assert.Equal(1, sent.GetProperty("challengeGeneration").GetInt32());
        Assert.True(Verifies(partnerKey, AnisEnrollmentClient.ProofMessage(submitted), sent.GetProperty("signature").GetString()!));

        // The key submission carried the PUBLIC half only.
        Assert.DoesNotContain("\"d\"", Encoding.UTF8.GetString(stub.RequestBodies[0]!), StringComparison.Ordinal);
        // Networks are agreed with Anis staff, never proposed with the key.
        Assert.DoesNotContain("\"cidrs\"", Encoding.UTF8.GetString(stub.RequestBodies[0]!), StringComparison.Ordinal);

        // The token is a secret: on no span, log or metric.
        Assert.NotEmpty(capture.Spans);
        Assert.DoesNotContain(Token, capture.Everything, StringComparison.Ordinal);
    }

    [Fact]
    public async Task A_refused_step_is_an_enrollment_exception()
    {
        using var responseKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);

        var stub = new SignedResponseStub(responseKey, ResponseKeyId)
        {
            SignedAt = Now,
            NoStore = true,
            Status = HttpStatusCode.Conflict,
            Body = """{"type":"https://developers.anis.ly/errors/challenge-expired","title":"t","status":409,"code":"challenge_expired"}""",
        };

        using var enrollment = AnisEnrollmentClient.Create(
            new Uri("https://partners.anis.ly"), Invitation, Token, KeysFor(responseKey), stub, new FixedClock(Now));

        var failure = await Assert.ThrowsAsync<EnrollmentRefusedException>(
            () => enrollment.SubmitProofAsync(
                new EnrollmentProofRequest { KeyId = Invitation, ChallengeGeneration = 1, Signature = new string('A', 86) },
                TestContext.Current.CancellationToken));

        Assert.Equal(PartnerErrorCode.ChallengeExpired, failure.Code);
    }

    [Fact]
    public async Task An_enrollment_call_is_measured_like_every_other_call()
    {
        using var responseKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        using var capture = new TelemetryCapture();

        var stub = new SignedResponseStub(responseKey, ResponseKeyId)
        {
            SignedAt = Now,
            NoStore = true,
            Body = $$"""{"invitationId":"{{Invitation:D}}","state":"pendingPublicKey"}""",
        };

        using var enrollment = AnisEnrollmentClient.Create(
            new Uri("https://partners.anis.ly"), Invitation, Token, KeysFor(responseKey), stub, new FixedClock(Now));

        var state = await enrollment.GetAsync(TestContext.Current.CancellationToken);

        Assert.Equal("pendingPublicKey", state.State);

        // The shared transport measures the enrollment call under its route template; the token is on no signal.
        var duration = Assert.Single(capture.Measurements, m => m.Instrument == "anis.partners.request.duration");
        Assert.Equal("default", duration.Tags[AnisPartnersTelemetry.Tags.Client]);
        Assert.Equal("/v1/enrollments/{invitationId}", duration.Tags[AnisPartnersTelemetry.Tags.Route]);
        Assert.Equal("GET", duration.Tags[AnisPartnersTelemetry.Tags.Method]);
        Assert.Equal("200", duration.Tags[AnisPartnersTelemetry.Tags.StatusCode]);
        Assert.DoesNotContain(Token, capture.Everything, StringComparison.Ordinal);
        Assert.Equal($"Enrollment {Token}", stub.LastRequest!.Headers.GetValues("Authorization").Single());
        Assert.Equal($"/v1/enrollments/{Invitation:D}", stub.LastRequest.RequestUri!.AbsolutePath);
        Assert.False(stub.LastRequest!.Headers.Contains("Signature"));
        Assert.False(stub.LastRequest.Headers.Contains("Signature-Input"));
    }

    [Fact]
    public async Task The_status_read_carries_the_key_end_date_and_tolerates_its_absence()
    {
        using var responseKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        var stub = new SignedResponseStub(responseKey, ResponseKeyId)
        {
            SignedAt = Now,
            NoStore = true,
            Body = $$"""{"keyId":"{{Invitation:D}}","state":"active","approvalState":"approved","keyExpiresAt":"2027-09-30T12:00:00+00:00"}""",
        };

        using var enrollment = AnisEnrollmentClient.Create(
            new Uri("https://partners.anis.ly"), Invitation, Token, KeysFor(responseKey), stub, new FixedClock(Now));

        var active = await enrollment.GetStatusAsync(TestContext.Current.CancellationToken);
        Assert.Equal(new DateTimeOffset(2027, 9, 30, 12, 0, 0, TimeSpan.Zero), active.KeyExpiresAt);

        stub.Body = $$"""{"keyId":"{{Invitation:D}}","state":"active","approvalState":"approved"}""";
        var withoutEndDate = await enrollment.GetStatusAsync(TestContext.Current.CancellationToken);
        Assert.Null(withoutEndDate.KeyExpiresAt);
    }

    [Theory]
    [MemberData(nameof(Vectors))]
    public async Task The_sdk_computes_the_thumbprint_Commands_computed(string path)
    {
        var vector = JsonDocument.Parse(await File.ReadAllTextAsync(path, TestContext.Current.CancellationToken)).RootElement;
        var jwk = vector.GetProperty("key").GetProperty("publicJwk");

        var computed = KeyThumbprint.Compute(new PartnerJwk
        {
            Kty = jwk.GetProperty("kty").GetString(),
            Crv = jwk.GetProperty("crv").GetString(),
            X = jwk.GetProperty("x").GetString(),
            Y = jwk.GetProperty("y").GetString(),
        });

        Assert.Equal(vector.GetProperty("keySubmissionResult").GetProperty("thumbprint").GetString(), computed);
    }

    [Fact]
    public void A_jwk_that_is_not_a_complete_p256_public_key_has_no_thumbprint()
    {
        using var key = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        var jwk = AnisEnrollmentClient.PublicJwkOf(key);

        Assert.Throws<ArgumentException>(() => KeyThumbprint.Compute(jwk with { Kty = "RSA" }));
        Assert.Throws<ArgumentException>(() => KeyThumbprint.Compute(jwk with { Crv = "P-384" }));
        Assert.Throws<ArgumentException>(() => KeyThumbprint.Compute(jwk with { X = null }));
        Assert.Throws<ArgumentException>(() => KeyThumbprint.Compute(jwk with { Y = jwk.Y![..^1] }));
        Assert.Throws<ArgumentException>(() => KeyThumbprint.Compute(jwk with { X = new string('+', 43) }));
    }

    [Fact]
    public void The_private_member_does_not_change_the_thumbprint()
    {
        using var key = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        var jwk = AnisEnrollmentClient.PublicJwkOf(key);

        Assert.Equal(KeyThumbprint.Compute(jwk), KeyThumbprint.Compute(jwk with { D = "ignored", Kid = "ignored" }));
    }

    [Fact]
    public async Task The_safety_code_is_derived_from_the_verified_thumbprint_never_taken_from_the_answer()
    {
        using var responseKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        using var partnerKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);

        var thumbprint = KeyThumbprint.Compute(AnisEnrollmentClient.PublicJwkOf(partnerKey));
        var stub = new SignedResponseStub(responseKey, ResponseKeyId)
        {
            SignedAt = Now,
            NoStore = true,
            Body = $$"""{"keyId":"{{Invitation:D}}","thumbprint":"{{thumbprint}}","safetyCode":"AAAA-BBBB-CCCC-DDDD","challenge":"c","challengeGeneration":1}""",
        };

        using var enrollment = AnisEnrollmentClient.Create(
            new Uri("https://partners.anis.ly"), Invitation, Token, KeysFor(responseKey), stub, new FixedClock(Now));

        var submitted = await enrollment.SubmitKeyAsync(KeyRequest(partnerKey), TestContext.Current.CancellationToken);

        Assert.Equal(SafetyCode.FromThumbprint(thumbprint), submitted.SafetyCode);
    }

    [Fact]
    public async Task A_key_Anis_answers_for_with_another_thumbprint_stops_the_enrollment_before_any_proof()
    {
        using var responseKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        using var partnerKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        using var otherKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);

        var other = KeyThumbprint.Compute(AnisEnrollmentClient.PublicJwkOf(otherKey));
        var stub = new SignedResponseStub(responseKey, ResponseKeyId)
        {
            SignedAt = Now,
            NoStore = true,
            Body = $$"""{"keyId":"{{Invitation:D}}","thumbprint":"{{other}}","safetyCode":"AAAA-BBBB-CCCC-DDDD","challenge":"c","challengeGeneration":1}""",
        };

        using var enrollment = AnisEnrollmentClient.Create(
            new Uri("https://partners.anis.ly"), Invitation, Token, KeysFor(responseKey), stub, new FixedClock(Now));

        var failure = await Assert.ThrowsAsync<EnrollmentKeyMismatchException>(
            () => enrollment.SubmitKeyAsync(KeyRequest(partnerKey), TestContext.Current.CancellationToken));

        Assert.Equal(KeyThumbprint.Compute(AnisEnrollmentClient.PublicJwkOf(partnerKey)), failure.LocalThumbprint);
        Assert.Equal(other, failure.ServerThumbprint);

        // Only the key submission went out; the answer's challenge was never handed back to build a proof on.
        Assert.Single(stub.Requests);
        Assert.DoesNotContain("challenge", failure.Message, StringComparison.Ordinal);
    }

    [Fact]
    public async Task An_answer_without_a_thumbprint_is_a_mismatch_too()
    {
        using var responseKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        using var partnerKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);

        var stub = new SignedResponseStub(responseKey, ResponseKeyId)
        {
            SignedAt = Now,
            NoStore = true,
            Body = $$"""{"keyId":"{{Invitation:D}}","challenge":"c","challengeGeneration":1}""",
        };

        using var enrollment = AnisEnrollmentClient.Create(
            new Uri("https://partners.anis.ly"), Invitation, Token, KeysFor(responseKey), stub, new FixedClock(Now));

        var failure = await Assert.ThrowsAsync<EnrollmentKeyMismatchException>(
            () => enrollment.SubmitKeyAsync(KeyRequest(partnerKey), TestContext.Current.CancellationToken));

